class Solution:
    def kLengthApart(self, nums: List[int], k: int) -> bool:
        pre = -k - 1
        for i, v in enumerate(nums):
            if v:
                if i - pre < k + 1:
                    return False
                else:
                    pre = i
        return True

class Solution(object):
    def maxPower(self, s):
        stack=[]
        mxpow=0
        for i in s:
            if stack and stack[-1]!=i:
                mxpow=max(mxpow,len(stack))
                stack=[]
                stack.append(i)
            else:
                stack.append(i)
        mxpow=max(mxpow,len(stack))
        return mxpow

