class Solution:
    def numWaterBottles(self, a: int, b: int) -> int:

        def sol(a,b,e,res):
            if a!=0: res += a
            if (a+e)<b: return res 
            a += e
            new=a//b
            e = a-(new*b)
            a=new
            return sol(a,b,e,res)

        return sol(a,b,0,0)

class Solution:
    def countOdds(self, low: int, high: int) -> int:        
        total_nums = high - low

        answer = total_nums // 2

        if low % 2 == 1 and high % 2 == 1:
            return answer + 1

        if low % 2 == 1:
            answer = answer + 1

        if high % 2 == 1:
            answer = answer + 1

        return answer

